  background: linear-gradient(135deg, rgba(21, 29, 40, 0.92), rgba(247, 150, 23, 0.35));
  border: 1px solid var(--light-orange);
  box-shadow: 0 10px 25px rgba(251, 185, 84, 0.3);
}
#card-grass-toucher .achievement-title {
  color: var(--lighter-orange);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.05em;
}
